/**
 * Menu icons (generated by tools/art/generate_art.py into resource_pack/textures/ui/shadowbound/).
 * A test checks that every path here exists in the resource pack.
 */
const BASE = "textures/ui/shadowbound/";
const NAMES = [
  "dogs", "hand", "sword", "squad", "shadow", "book", "clan", "gear", "recall", "ritual", "summon", "ability", "follow",
  "protect", "guard", "hunt", "back", "lock", "destroyed", "energy", "info", "canon", "on", "off", "text", "build",
] as const;
export type IconName = (typeof NAMES)[number];
export const ICON = Object.fromEntries(NAMES.map((n) => [n, BASE + n])) as Record<IconName, string>;
export const ICON_NAMES: readonly string[] = NAMES;
export const shikiIcon = (sp: string): string => `${BASE}sk_${sp}`;
export const personaIcon = (p: string): string => `${BASE}p_${p}`;
export const techIcon = (id: string): string => `${BASE}t_${id}`;
export const abilityIcon = (icon: string): string => `${BASE}a_${icon}`;
export const clanIcon = (id: string): string => `${BASE}clan_${id}`;
export const techCrest = (id: string): string => `${BASE}tech_${id}`;
export const itemIcon = (atlas: string): string => `textures/items/${atlas}`;

/** Best icon for a menu label (used by the older squad menus). */
export function iconFor(label: string): string {
  const t = label.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/§./g, "");
  const rules: [RegExp, IconName][] = [
    [/desinvoc|pode ir|recolher/, "recall"], [/configura/, "gear"], [/texto|ordem para/, "text"], [/escolher|esquadrao|companheira/, "squad"],
    [/criatura|shikigami/, "dogs"], [/invocar/, "summon"], [/seguir/, "follow"], [/proteg/, "protect"], [/guarda|parad/, "guard"],
    [/atacar|cacar/, "hunt"], [/entreg|inventario|me de|devolv|pegar de volta/, "shadow"], [/constru|madeira|coletar|minerar|fabricar|comida/, "build"],
    [/cancel/, "off"], [/voltar|←|«/, "back"],
  ];
  for (const [re, n] of rules) if (re.test(t)) return ICON[n];
  return ICON.canon;
}
